pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testRegression_property() public {
        vm.prank(c.owner());
        c.pause();

        bool ok;
        try c.acceptOwnership() { ok = true; } catch { ok = true; }

        bool currentPaused = c.paused();
        assertTrue(currentPaused == true, "paused should be true after pause()");
    }
}
